import { load as yamlLoad } from "js-yaml";

export type LogEntry = {
  action: string;
  by: string;
  at: string;
  note?: string;
};

export type ParsedTask = {
  id: string;
  title: string;
  status: string;
  dependsOn: string[];
  description?: string;
  priority?: string;
  execution?: { actor_type: string; last_updated_by?: string; last_updated_at?: string };
  branch?: string;
  pr?: { url?: string; status?: string };
  workspace_pr?: { url?: string; status?: string };
  blockedReason?: string;
  blockedContext?: Record<string, unknown>;
  log?: LogEntry[];
};

export type ParsedFeature = {
  id: string;
  title: string;
  featureStatus: string;
  tasks: ParsedTask[];
};

type RawFeatureStatus = {
  feature_id?: string;
  title?: string;
  feature_status?: string;
  stage?: string;
};

type RawTask = {
  id?: string;
  title?: string;
  status?: string;
  depends_on?: string[];
  description?: string;
  priority?: string;
  execution?: { actor_type?: string; last_updated_by?: string; last_updated_at?: string };
  branch?: string;
  pr?: { url?: string; status?: string };
  workspace_pr?: { url?: string; status?: string };
  blocked_reason?: string;
  blocked_context?: Record<string, unknown>;
  log?: Array<{ action?: string; by?: string; at?: string; note?: string }>;
};

export function parseFeatureStatus(
  raw: string,
  featureId?: string,
): RawFeatureStatus {
  try {
    return (yamlLoad(raw) as RawFeatureStatus) ?? {};
  } catch (err) {
    const id = featureId ?? "<unknown>";
    console.warn(`[yaml-parser] Failed to parse status.yaml for ${id}:`, err);
    return {};
  }
}

export function parseTaskYaml(id: string, raw: string): ParsedTask | null {
  let data: RawTask;
  try {
    data = (yamlLoad(raw) as RawTask) ?? {};
  } catch (err) {
    console.warn(`[yaml-parser] Failed to parse task YAML for ${id}:`, err);
    return null;
  }

  if (!data || typeof data !== "object") {
    console.warn(`[yaml-parser] Malformed task YAML for ${id}: not an object`);
    return null;

