3	import { useMemo } from "react";
4	import { useBoardContext } from "../KanbanBoard/KanbanBoard.context";
5	import { FeatureListRow } from "./FeatureListRow";
6	import type { ParsedFeature } from "@/services/yaml-parser";
7	import {
8	  matchesFeatureModeSearch,
9	  matchesFeatureModeStatusFilter,
10	} from "../../lib/filter";
11	import {
12	  FEATURE_STATUS_OPTIONS,
13	  getFeatureStatusColor,
14	  getFeatureStatusLabel,
15	} from "../../lib/status";
16	import {
17	  AccessDeniedState,
18	  EmptyBoardState,
19	  NetworkErrorState,
20	  NoWorkflowDataState,
21	  ParseErrorState,
22	} from "../ErrorStates";
23	
24	const MIN_FEATURE_COLUMN_WIDTH = 180;
25	
26	type FeatureStatusColumn = {
27	  key: string;
28	  label: string;
29	  color: string;
30	};
31	
32	function getFeatureStatusColumns(
33	  features: ParsedFeature[],
34	): FeatureStatusColumn[] {
35	  const columns: FeatureStatusColumn[] = [...FEATURE_STATUS_OPTIONS];
36	  const knownStatuses = new Set(columns.map((column) => column.key));
37	
38	  for (const feature of features) {
39	    if (knownStatuses.has(feature.featureStatus)) continue;
40	    knownStatuses.add(feature.featureStatus);
41	    columns.push({
42	      key: feature.featureStatus,
43	      label: getFeatureStatusLabel(feature.featureStatus),
44	      color: getFeatureStatusColor(feature.featureStatus),
45	    });
46	  }
47	
48	  return columns;
49	}
