97	export function FeatureBoardView() {
98	  const {
99	    features,
100	    loading,
101	    error,
102	    featureSearchQuery,
103	    featureActiveFilters,
104	    setSelectedFeature,
105	  } = useBoardContext();
106	
107	  const visibleFeatures = useMemo(
108	    () =>
109	      features.filter(
110	        (f) =>
111	          matchesFeatureModeSearch(f, featureSearchQuery) &&
112	          matchesFeatureModeStatusFilter(f, featureActiveFilters.statuses),
113	      ),
114	    [features, featureSearchQuery, featureActiveFilters],
115	  );
116	
117	  const featureStatusColumns = useMemo(
118	    () => getFeatureStatusColumns(visibleFeatures),
119	    [visibleFeatures],
120	  );
121	
122	  const featureStatusCounts = useMemo(() => {
123	    const counts: Record<string, number> = {};
124	    for (const column of featureStatusColumns) {
125	      counts[column.key] = 0;
126	    }
127	
128	    for (const feature of visibleFeatures) {
129	      counts[feature.featureStatus] ??= 0;
130	      counts[feature.featureStatus] += 1;
131	    }
132	
133	    return counts;
134	  }, [featureStatusColumns, visibleFeatures]);
135	
136	  let content;
137	  if (loading) {
138	    content = (
139	      <div className="flex flex-1 items-center justify-center">
140	        <p className="text-sm text-text-muted">Loading features...</p>
141	      </div>
142	    );
143	  } else if (error) {
144	    if (error.kind === "access_denied") {
145	      content = <AccessDeniedState message={error.message} />;
146	    } else if (error.kind === "not_found") {
147	      content = <NoWorkflowDataState message={error.message} />;
148	    } else if (error.kind === "parse_error") {
149	      content = <ParseErrorState message={error.message} />;
150	    } else {
151	      content = <NetworkErrorState message={error.message} />;
152	    }
153	  } else if (features.length === 0) {
154	    content = <EmptyBoardState />;
155	  } else if (visibleFeatures.length === 0) {
156	    content = (
157	      <EmptyState message="No features match the current search or filters." />
158	    );
159	  } else {
160	    const gridTemplateColumns = `repeat(${featureStatusColumns.length}, minmax(${MIN_FEATURE_COLUMN_WIDTH}px, 1fr))`;
161	
162	    content = (
163	      <div className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden">
164	        <div
165	          data-feature-kanban-board
166	          className="min-h-full w-full"
167	          style={{
168	            minWidth: MIN_FEATURE_COLUMN_WIDTH * featureStatusColumns.length,
169	          }}
